    "fullSolution": "\"\"\"Exercise 00-foundations.T2.00d - reference solution.\n\nOne idea repeated: a derivative is multiplication by j*omega, so a differential equation becomes a\ncomplex ratio, and that ratio carries both numbers a sine response has - amplitude and phase. The\nresonance peak is the one place where the formula needs care: it is not at omega_n unless zeta is\nzero, and it only exists above zeta = 1/sqrt(2) as a peak at all.\n\"\"\"\n\nimport cmath\nimport math\n\nimport mechalab_plant as plant\n\n\ndef to_polar(z):\n    \"\"\"(magnitude, phase_rad).\"\"\"\n    return abs(z), cmath.phase(z)\n\n\ndef to_rect(magnitude, phase_rad):\n    \"\"\"m e^{j phi}.\"\"\"\n    return cmath.rect(magnitude, phase_rad)\n\n\ndef first_order_response(tau, omega):\n    \"\"\"H(j omega) = 1 / (1 + j omega tau).\"\"\"\n    return 1.0 / (1.0 + 1j * omega * tau)\n\n\ndef second_order_response(wn, zeta, omega):\n    \"\"\"G(j omega) for the canonical second-order system.\"\"\"\n    s = 1j * omega\n    return (wn * wn) / (s * s + 2.0 * zeta * wn * s + wn * wn)\n\n\ndef magnitude_db(h):\n    \"\"\"20 log10 |h|.\"\"\"\n    return 20.0 * math.log10(abs(h))\n\n\ndef phase_deg(h):\n    \"\"\"Phase in degrees.\"\"\"\n    return math.degrees(cmath.phase(h))\n\n\ndef resonance_peak(wn, zeta):\n    \"\"\"(omega_r, peak) of |G|, or (0.0, 1.0) when the magnitude never peaks above 1.\"\"\"\n    if zeta <= 0.0 or zeta >= 1.0 / math.sqrt(2.0):\n        return 0.0, 1.0\n    root = math.sqrt(1.0 - 2.0 * zeta * zeta)\n    return wn * root, 1.0 / (2.0 * zeta * math.sqrt(1.0 - zeta * zeta))\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 00-foundations.T2.00d.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    mag, phase = to_polar(1.0 - 1.0j)\n    assert abs(mag - math.sqrt(2.0)) < 1e-12, \"magnitude\"\n    assert abs(phase + math.pi / 4.0) < 1e-12, \"phase is in the fourth quadrant\"\n    z = to_rect(2.0, math.pi / 3.0)\n    assert abs(z.real - 1.0) < 1e-12 and abs(z.imag - math.sqrt(3.0)) < 1e-12, \"Euler's formula\"\n    checks += 1\n\n    h = first_order_response(0.01, 100.0)\n    assert abs(abs(h) - 1.0 / math.sqrt(2.0)) < 1e-12, \"cutoff magnitude\"\n    assert abs(phase_deg(h) + 45.0) < 1e-9, \"cutoff phase\"\n    assert abs(magnitude_db(h) + 3.0103) < 1e-4, \"cutoff in dB\"\n    checks += 1\n\n    g = second_order_response(100.0, 0.05, 100.0)\n    assert abs(abs(g) - 10.0) < 1e-9, \"resonance gain\"\n    assert abs(magnitude_db(g) - 20.0) < 1e-9, \"resonance dB\"\n    assert abs(phase_deg(g) + 90.0) < 1e-9, \"resonance phase\"\n    checks += 1\n\n    g10 = second_order_response(100.0, 0.05, 1000.0)\n    assert abs(magnitude_db(g10) + 39.9127) < 1e-3, \"a decade above resonance\"\n    assert abs(phase_deg(g10) + 179.4213) < 1e-3, \"phase a decade above\"\n    checks += 1\n\n    assert abs(magnitude_db(10.0) - 20.0) < 1e-12, \"20 log10, not 10 log10\"\n    assert abs(magnitude_db(0.1) + 20.0) < 1e-12, \"amplitude decibels\"\n    assert abs(phase_deg(-1.0j) + 90.0) < 1e-12, \"degrees at the Bode boundary\"\n    checks += 1\n\n    omega_r, peak = resonance_peak(100.0, 0.2)\n    assert abs(omega_r - 100.0 * math.sqrt(1.0 - 2.0 * 0.04)) < 1e-9, \"peak frequency\"\n    at_peak = abs(second_order_response(100.0, 0.2, omega_r))\n    assert abs(at_peak - peak) < 1e-6, \"the peak is a point on the curve\"\n    assert resonance_peak(100.0, 0.9) == (0.0, 1.0), \"no peak when overdamped enough\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - polar form, first order, resonance, decade rolloff, \"\n          \"decibels, peak location\" % checks)\n\n\n_selfcheck()\n",
