    "starterCode": "\"\"\"Exercise 00-foundations.T2.00f - the learner's file.\n\nThree tools a digital controller needs before it can trust a sample: what the Nyquist limit folds\nhigh frequencies down to, where Tustin actually puts a frequency, and how an error ellipse grows\nacross one step. Fill the seven TODOs:\n\n    EXERCISE_TARGET=exercises/00-foundations.T2.00f/starter.py \\\n        python3 -m unittest discover -s exercises/00-foundations.T2.00f -p 'test_*.py'\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant\n\n\ndef nyquist_hz(fs):\n    \"\"\"The highest frequency a sample rate `fs` can represent, in Hz.\"\"\"\n    raise NotImplementedError(\"TODO 1: fs / 2\")\n\n\ndef alias_hz(f_sig, fs):\n    \"\"\"The frequency in [0, fs/2] that `f_sig` appears as after sampling at `fs`.\"\"\"\n    raise NotImplementedError(\"TODO 2: fold with fmod and mirror the second half down\")\n\n\ndef tustin_hz(omega_rad_s, fs):\n    \"\"\"Where unwarped Tustin actually places an analog frequency, in Hz.\"\"\"\n    raise NotImplementedError(\"TODO 3: digital angle 2 atan(omega Ts / 2), then divide by 2 pi Ts\")\n\n\ndef prewarp_omega(f0_hz, fs):\n    \"\"\"Analog prototype frequency that lands a Tustin filter exactly on f0_hz.\"\"\"\n    raise NotImplementedError(\"TODO 4: (2 / Ts) tan(pi f0 / fs)\")\n\n\ndef notch_coeffs(f0_hz, fs, q):\n    \"\"\"(b0, b1, b2, a1, a2) for a unity-gain notch at f0_hz with quality factor q; a0 is 1.\"\"\"\n    raise NotImplementedError(\"TODO 5: alpha = sin(w0) / (2 q); b0 = b2 = 1 / (1 + alpha)\")\n\n\ndef apply_biquad(coeffs, samples):\n    \"\"\"Run the TDF-II biquad over `samples` and return one output sample per input.\"\"\"\n    raise NotImplementedError(\"TODO 6: two delay states, w1 and w2, updated in that order\")\n\n\ndef covariance_propagate(a, sigma, q):\n    \"\"\"One predict step: A Sigma A^T + Q, for 2x2 matrices.\"\"\"\n    raise NotImplementedError(\"TODO 7: the sandwich rule, both sides of Sigma\")\n\ndef simulate_discrete(ad, bd, x0, u, steps):\n    \"\"\"Kept from 00e: iterate x_{k+1} = Ad x_k + Bd u with a constant u.\"\"\"\n    x = list(x0)\n    for _ in range(steps):\n        x = [sum(ad[i][j] * x[j] for j in range(2)) + bd[i][0] * u for i in range(2)]\n    return x\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 00-foundations.T2.00f.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert nyquist_hz(4000.0) == 2000.0, \"Nyquist\"\n    assert abs(alias_hz(3150.0, 4000.0) - 850.0) < 1e-12, \"one fold\"\n    assert abs(alias_hz(2700.0, 2000.0) - 700.0) < 1e-12, \"fold below fs\"\n    assert abs(alias_hz(3000.0, 4000.0) - 1000.0) < 1e-12, \"mirror the second half\"\n    assert abs(alias_hz(100.0, 4000.0) - 100.0) < 1e-12, \"below Nyquist is untouched\"\n    checks += 1\n\n    landed = tustin_hz(2.0 * math.pi * 850.0, 4000.0)\n    assert abs(landed - 749.4803) < 1e-3, \"unwarped Tustin lands low\"\n    assert abs(850.0 - landed - 100.5197) < 1e-3, \"the missed hertz\"\n    checks += 1\n\n    wa = prewarp_omega(850.0, 4000.0)\n    assert abs(wa - 6306.6915) < 1e-3, \"pre-warped analog frequency\"\n    assert abs(tustin_hz(wa, 4000.0) - 850.0) < 1e-9, \"round trip lands on target\"\n    checks += 1\n\n    b0, b1, b2, a1, a2 = notch_coeffs(850.0, 4000.0, 5.0)\n    alpha = math.sin(2.0 * math.pi * 850.0 / 4000.0) / 10.0\n    assert abs(b0 - 1.0 / (1.0 + alpha)) < 1e-12, \"normalized b0\"\n    assert abs(b2 - b0) < 1e-15 and abs(a1 - b1) < 1e-15, \"notch symmetry\"\n    dc = (b0 + b1 + b2) / (1.0 + a1 + a2)\n    assert abs(dc - 1.0) < 1e-12, \"unity DC gain\"\n    checks += 1\n\n    step = apply_biquad((b0, b1, b2, a1, a2), [1.0] * 1000)\n    assert len(step) == 1000 and abs(step[-1] - 1.0) < 1e-9, \"a step passes the notch at DC\"\n    tone = [math.sin(2.0 * math.pi * 850.0 * k / 4000.0) for k in range(4000)]\n    out = apply_biquad((b0, b1, b2, a1, a2), tone)\n    energy_in = sum(v * v for v in tone[2000:])\n    energy_out = sum(v * v for v in out[2000:])\n    assert energy_out < 1e-6 * energy_in, \"a true null at 850 Hz\"\n    checks += 1\n\n    sigma = covariance_propagate([[1.0, 0.1], [0.0, 1.0]], [[1.0, 0.0], [0.0, 4.0]],\n                                 [[0.0, 0.0], [0.0, 0.0]])\n    assert abs(sigma[0][0] - 1.04) < 1e-12, \"variance grows by the cross term\"\n    assert abs(sigma[0][1] - 0.4) < 1e-12 and abs(sigma[1][0] - 0.4) < 1e-12, \"symmetric\"\n    assert abs(sigma[1][1] - 4.0) < 1e-12, \"the second variance is untouched\"\n    checks += 1\n\n    assert covariance_propagate([[1.0, 0.0], [0.0, 1.0]], [[2.0, 0.5], [0.5, 3.0]],\n                                [[0.25, 0.0], [0.0, 0.75]])[0][0] == 2.25, \"Q is added\"\n\n    print(\"SELF-CHECK PASS: %d checks - Nyquist, folding and mirroring, warping, pre-warp round \"\n          \"trip, biquad normalization, the null, DC gain, covariance sandwich\" % checks)\n\n\n_selfcheck()\n",
