    "fullSolution": "\"\"\"Exercise 02-mechanics.T2.02a - reference solution.\n\nThis is the file the tests are expected to pass. It is also the file a learner compares against\n*after* attempting the exercise, not instead of it.\n\nThe one thing to notice: `gravity_from_com_jacobians` never mentions the arm's gravity formula.\nIt builds two CoM Jacobians and sums J^T w, which reproduces `plant.gravity_torque` to ~1e-16\nN*m. That identity is what lets a controller feed a payload forward without new physics.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant\n\n\ndef jacobian(q1, q2, l1=plant.L1, l2=plant.L2):\n    \"\"\"The 2x2 geometric Jacobian of the tip, m/rad.\"\"\"\n    s1, c1 = math.sin(q1), math.cos(q1)\n    s12, c12 = math.sin(q1 + q2), math.cos(q1 + q2)\n    return [[-l1 * s1 - l2 * s12, -l2 * s12],\n            [l1 * c1 + l2 * c12, l2 * c12]]\n\n\ndef joint_torques(J, force):\n    \"\"\"tau = J^T F: the tip force mapped into the joints, N*m.\"\"\"\n    return (J[0][0] * force[0] + J[1][0] * force[1],\n            J[0][1] * force[0] + J[1][1] * force[1])\n\n\ndef gravity_from_com_jacobians(q1, q2):\n    \"\"\"Gravity holding torque from the two CoM Jacobians, N*m.\"\"\"\n    s1, c1 = math.sin(q1), math.cos(q1)\n    s12, c12 = math.sin(q1 + q2), math.cos(q1 + q2)   # the elbow's world angle, not q2\n    j_link1 = [[-plant.LC1 * s1, 0.0],\n               [plant.LC1 * c1, 0.0]]\n    j_link2 = [[-plant.L1 * s1 - plant.LC2 * s12, -plant.LC2 * s12],\n               [plant.L1 * c1 + plant.LC2 * c12, plant.LC2 * c12]]\n    tau1 = 0.0\n    tau2 = 0.0\n    for j_com, mass in ((j_link1, plant.M1), (j_link2, plant.M2)):\n        t1, t2 = joint_torques(j_com, (0.0, mass * plant.G))\n        tau1 += t1\n        tau2 += t2\n    return tau1, tau2\n\n\ndef singular_elbow_angles():\n    \"\"\"det J = l1 l2 sin(q2) vanishes at the stretched and folded poses.\"\"\"\n    return (0.0, math.pi)\n\n\ndef potential_gradient(q1, q2, m_p=0.05, h=1e-6):\n    \"\"\"dU/dq for U = m_p g y_tip, by central differences.\"\"\"\n\n    def potential(a1, a2):\n        return m_p * plant.G * plant.fk(a1, a2)[1]\n\n    return ((potential(q1 + h, q2) - potential(q1 - h, q2)) / (2.0 * h),\n            (potential(q1, q2 + h) - potential(q1, q2 - h)) / (2.0 * h))\n\n\ndef payload_run(m_payload, compensate):\n    \"\"\"The capstone's figure-8 with a point mass at the tip, graded on tip error.\"\"\"\n    q_des = plant.ik(*plant.figure8_target(0.0))\n    state = (q_des[0], q_des[1], 0.0, 0.0)\n    previous = q_des\n    sum_sq = 0.0\n    peak_mm = 0.0\n\n    for step in range(plant.TICKS):\n        t = step * plant.DT\n        x_des, y_des = plant.figure8_target(t)\n        q_des = plant.ik(x_des, y_des)\n        if step:\n            dq_des = ((q_des[0] - previous[0]) / plant.DT,\n                      (q_des[1] - previous[1]) / plant.DT)\n        else:\n            dq_des = (0.0, 0.0)\n        previous = q_des\n\n        tau_g = plant.gravity_torque(state[0], state[1])\n        payload = joint_torques(jacobian(state[0], state[1]),\n                                (0.0, m_payload * plant.G))\n        feed = payload if compensate else (0.0, 0.0)\n\n        tau1 = (plant.KP1 * (q_des[0] - state[0])\n                + plant.KD1 * (dq_des[0] - state[2]) + tau_g[0] + feed[0])\n        tau2 = (plant.KP2 * (q_des[1] - state[1])\n                + plant.KD2 * (dq_des[1] - state[3]) + tau_g[1] + feed[1])\n        tau = (max(-plant.TAU_LIMIT, min(plant.TAU_LIMIT, tau1)),\n               max(-plant.TAU_LIMIT, min(plant.TAU_LIMIT, tau2)))\n\n        pulse = plant.disturbance_torque(t)\n        state = plant.step_arm(state, tau,\n                               dist=(pulse[0] - payload[0], pulse[1] - payload[1]))\n\n        error_mm = math.dist((x_des, y_des), plant.fk(state[0], state[1])) * 1000.0\n        sum_sq += error_mm * error_mm\n        peak_mm = max(peak_mm, error_mm)\n\n    return {\"rms_mm\": math.sqrt(sum_sq / plant.TICKS), \"peak_mm\": peak_mm}\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 02-mechanics.T2.02a.\n\nThis file is appended verbatim to the exercise entry the workbench loads, after the learner's code.\nThat is why it is stdlib-only and imports nothing but `math` and `mechalab_plant`: Pyodide has both,\nand the runner writes the plant into its filesystem before the program runs.\n\nIt is a coarser check than `test_behavior.py` (no unittest, one PASS line), and deliberately so: the\nbrowser grades by comparing stdout. The full suite is still the CI authority, and both read the same\nfunctions.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant\n\n\ndef _selfcheck():\n    checks = 0\n    poses = [(0.0, math.pi / 2.0), (0.37, 1.15), (-1.10, 0.62), (0.0, 0.0), (2.4, -0.9)]\n\n    for q1, q2 in poses:\n        J = jacobian(q1, q2)\n        h = 1e-6\n        x1p, y1p = plant.fk(q1 + h, q2)\n        x1m, y1m = plant.fk(q1 - h, q2)\n        x2p, y2p = plant.fk(q1, q2 + h)\n        x2m, y2m = plant.fk(q1, q2 - h)\n        want = [[(x1p - x1m) / (2 * h), (x2p - x2m) / (2 * h)],\n                [(y1p - y1m) / (2 * h), (y2p - y2m) / (2 * h)]]\n        for r in range(2):\n            for c in range(2):\n                assert abs(J[r][c] - want[r][c]) < 1e-6, \"jacobian at q=(%.3f, %.3f)\" % (q1, q2)\n        checks += 1\n\n    long_arm = jacobian(0.4, 0.9, 0.30, 0.25)\n    assert abs(long_arm[0][0] - jacobian(0.4, 0.9)[0][0]) > 0.15, \"jacobian ignored l1/l2\"\n    checks += 1\n\n    J = jacobian(0.37, 1.15)\n    F = (3.0, -7.0)\n    tau = joint_torques(J, F)\n    assert abs(tau[0] - (J[0][0] * F[0] + J[1][0] * F[1])) < 1e-12, \"tau is not J^T F\"\n    dq = (0.21, -0.13)\n    tip_v = (J[0][0] * dq[0] + J[0][1] * dq[1], J[1][0] * dq[0] + J[1][1] * dq[1])\n    assert abs(tau[0] * dq[0] + tau[1] * dq[1] - (F[0] * tip_v[0] + F[1] * tip_v[1])) < 1e-12, \"virtual work\"\n    checks += 1\n\n    for q1, q2 in ((0.0, 0.0), (0.0, math.pi / 2.0), (math.pi / 2.0, 0.0), (0.55, 1.2)):\n        got = gravity_from_com_jacobians(q1, q2)\n        want = plant.gravity_torque(q1, q2)\n        assert abs(got[0] - want[0]) < 1e-12 and abs(got[1] - want[1]) < 1e-12, \\\n            \"gravity differs from the plant at q=(%.3f, %.3f)\" % (q1, q2)\n    checks += 1\n\n    assert tuple(singular_elbow_angles()) == (0.0, math.pi), \"singular elbow angles\"\n    checks += 1\n\n    for q1, q2 in ((0.0, math.pi / 2.0), (0.30, 0.60)):\n        by_force = joint_torques(jacobian(q1, q2), (0.0, 0.05 * plant.G))\n        by_energy = potential_gradient(q1, q2)\n        assert abs(by_force[0] - by_energy[0]) < 1e-9, \"dU/dq1 vs J^T F\"\n        assert abs(by_force[1] - by_energy[1]) < 1e-9, \"dU/dq2 vs J^T F\"\n    checks += 1\n\n    on = payload_run(0.20, True)\n    off = payload_run(0.20, False)\n    assert on[\"rms_mm\"] < 0.914, \"compensated payload run should match the capstone (%.3f mm)\" % on[\"rms_mm\"]\n    assert off[\"rms_mm\"] > 2.5 * on[\"rms_mm\"], \"uncompensated payload run should be much worse\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - jacobian, J^T, gravity, singular, energy, payload\" % checks)\n\n\n_selfcheck()\n",
