    "starterCode": "\"\"\"Exercise 05-control.T2.05a - the learner's file.\n\nMargins, the sensitivity pair, Bryson's weights, an observer's error matrix and a discrete LQR\ngain. Fill the seven TODOs:\n\n    EXERCISE_TARGET=exercises/05-control.T2.05a/starter.py \\\n        python3 -m unittest discover -s exercises/05-control.T2.05a -p 'test_*.py'\n\"\"\"\n\nimport cmath\nimport math\n\nimport mechalab_plant as plant\n\n\ndef phase_margin_deg(loop):\n    \"\"\"Phase margin at a gain crossover, with the loop's lag unwrapped into (-360, 0].\"\"\"\n    raise NotImplementedError(\"TODO 1: 180 + the phase in degrees, after unwrapping a positive angle\")\n\n\ndef phase_loss_deg(omega_gc, tau_d):\n    \"\"\"Degrees of phase a transport delay eats at the gain crossover.\"\"\"\n    raise NotImplementedError(\"TODO 2: the delay angle is omega * tau, in radians -> degrees\")\n\n\ndef st(loop):\n    \"\"\"`S = 1/(1+L)` and `T = L/(1+L)`; their sum is one at every frequency.\"\"\"\n    raise NotImplementedError(\"TODO 3: both share the denominator; T is not 1/S\")\n\n\ndef gain_crossover(loop_fn, w_lo=1e-3, w_hi=1e4, iterations=200):\n    \"\"\"Bisect for the frequency where |L(jw)| = 1; raise ValueError when the bracket has no crossing.\"\"\"\n    raise NotImplementedError(\"TODO 4: check the bracket's signs first, then halve it\")\n\n\ndef bryson_weights(x_max, u_max):\n    \"\"\"Bryson's rule: `Q_ii = 1/x_max_i^2`, `R = 1/u_max^2`.\"\"\"\n    raise NotImplementedError(\"TODO 5: squared, not linear - the units have to cancel\")\n\n\ndef observer_spectral_radius(ad, c, l):\n    \"\"\"Spectral radius of `Ad - L C` (two states, one measurement).\"\"\"\n    raise NotImplementedError(\"TODO 6: build Ad - L C, then its eigenvalues from trace and determinant\")\n\n\ndef lqr_gain(ad, bd, q_diag, r):\n    \"\"\"Discrete LQR gain for `u = -K x`, from the Riccati fixed point.\"\"\"\n    raise NotImplementedError(\"TODO 7: iterate P <- A'PA - A'PB (R + B'PB)^-1 B'PA + Q to its fixed point\")\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 05-control.T2.05a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport cmath\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    def loop(omega):\n        s = 1j * omega\n        return 100.0 / (s * (0.01 * s + 1.0))\n\n    w_gc = gain_crossover(loop)\n    assert abs(w_gc - 78.6151) < 1e-3, \"gain crossover\"\n    assert abs(abs(loop(w_gc)) - 1.0) < 1e-9, \"the crossover really is unity gain\"\n    checks += 1\n\n    pm = phase_margin_deg(loop(w_gc))\n    assert abs(pm - 51.8273) < 1e-3, \"phase margin\"\n    lagging = cmath.rect(0.9, math.radians(-200.0))\n    assert abs(phase_margin_deg(lagging) + 20.0) < 1e-9, \"a loop past -180 has negative margin\"\n    checks += 1\n\n    loss = phase_loss_deg(78.61514, 0.005)\n    assert abs(loss - 22.5216) < 1e-2, \"5 ms of transport delay\"\n    assert abs(phase_margin_deg(loop(w_gc)) - loss - 29.3057) < 1e-2, \"the margin after the delay\"\n    checks += 1\n\n    s, t = st(loop(w_gc))\n    assert abs((s + t) - 1.0) < 1e-12, \"S + T = 1\"\n    assert abs(abs(s) - 1.1441) < 1e-3, \"sensitivity at crossover\"\n    checks += 1\n\n    q_diag, r = bryson_weights([0.05, 0.10], 5.0)\n    assert abs(q_diag[0] - 400.0) < 1e-9 and abs(q_diag[1] - 100.0) < 1e-9, \"Bryson Q\"\n    assert abs(r - 0.04) < 1e-12, \"Bryson R\"\n    checks += 1\n\n    radius = observer_spectral_radius([[1.0, 0.001], [0.0, 0.99]], [1.0, 0.0], [0.19, 9.0])\n    assert abs(radius - math.sqrt(0.8109)) < 1e-3, \"observer error radius\"\n    assert radius < 1.0, \"the observer must converge\"\n    checks += 1\n\n    ad_model = [[1.0, 0.001], [0.0, 0.99]]\n    b_model = [0.0, 0.001]\n    k = lqr_gain(ad_model, [[0.0], [0.001]], [1.0, 1.0], 1.0)\n    m = [[ad_model[i][j] - b_model[i] * k[j] for j in range(2)] for i in range(2)]\n    tr = m[0][0] + m[1][1]\n    det = m[0][0] * m[1][1] - m[0][1] * m[1][0]\n    disc = cmath.sqrt(tr * tr - 4.0 * det)\n    rho = max(abs(0.5 * (tr + disc)), abs(0.5 * (tr - disc)))\n    assert rho < 1.0, \"the LQR gain stabilises the model\"\n    assert k[0] > 0.0 and k[1] > 0.0, \"both states are fed back\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - crossover, margin and its unwrap, delay loss, S + T, \"\n          \"Bryson weights, observer radius and the LQR gain\" % checks)\n\n\n_selfcheck()\n",
